                    self.select_tab(Some(ix), cx);
                    view.update(cx, |view, cx| view.reload_from_disk(window, cx));
                }
                ConflictChoice::Merge => {
                    self.select_tab(Some(ix), cx);
                    view.update(cx, |view, cx| view.start_merge(window, cx));
                }
            }
        }
        self.ask_next_conflict(window, cx);
