/// A reasoning effort level a harness can be told.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Effort {
    /// As the harness is told it, with `--model-reasoning-effort`.
    pub id: String,
    /// What the picker reads.
    pub label: String,
}

/// The levels `agent` can be told: Codex's low, medium, and high; none for
/// Claude Code or OpenCode, which take no such setting.
pub fn available(agent: Agent) -> Vec<Effort> {
    match agent {
        Agent::Codex => [("low", "Low"), ("medium", "Medium"), ("high", "High")]
            .into_iter()
            .map(|(id, label)| Effort {
                id: id.into(),
        dirs::config_dir()?
            .join("suspense")
            .join(format!("model-{}", agent.command())),
    )
}

/// The model chosen for `agent`, by its id; none for Default.
pub fn chosen(agent: Agent) -> Option<String> {
    with_chosen(|chosen| {
        chosen
            .entry(agent)
            .or_insert_with(|| {
                file(agent)
                    .and_then(|file| std::fs::read_to_string(file).ok())
                    .map(|text| text.trim().to_string())
                    .filter(|text| !text.is_empty())
            })
            .clone()
    })
}

/// Chooses `model` for `agent`, none for Default, and remembers it.
pub fn choose(agent: Agent, model: Option<String>) {
    if let Some(file) = file(agent) {
        if let Some(dir) = file.parent() {
            std::fs::create_dir_all(dir).ok();
        }
        // Only a convenience, so failing to keep it is ignored.
        std::fs::write(&file, model.as_deref().unwrap_or_default()).ok();
    }
    with_chosen(|chosen| chosen.insert(agent, model));
}

/// What the picker reads for `model`, `agent`'s: its label, or "Default".
pub fn label(agent: Agent, model: Option<&str>) -> String {
    let Some(model) = model else {
        return "Default".into();
    };
    available(agent)
        .into_iter()
        .find(|known| known.id == model)
        .map_or_else(
            || model.rsplit('/').next().unwrap_or(model).to_string(),
            |known| known.label,
        )
}

