                    .ghost()
                    .xsmall()
                    .label(label)
                    .tooltip(SharedString::from(tip))
                    .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                        for choice in Level::ALL {
