/// The story open beneath its row, and its editors.
struct OpenStory {
    name: String,
    title: Entity<InputState>,
    prompt: Entity<EditorState>,
    completion: Entity<CompletionMenu>,
    fit: GrowToFit,
    _subscriptions: Vec<Subscription>,
}

/// The box saying what is wanted, for Draft stories.
struct DraftBox {
    input: Entity<TextareaState>,
    running: bool,
    error: Option<String>,
    _run: Option<Task<()>>,
}

/// A story's row dragged.
#[derive(Clone)]
struct StoryDrag {
    name: String,
    title: SharedString,
    mode: SendMode,
}

impl Render for StoryDrag {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        h_flex()
            .gap_2()
            .px_3()
            .h(ROW_HEIGHT)
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .shadow_md()
            .text_sm()
            .child(mode_pill_label(self.mode, cx))
            .child(self.title.clone())
    }
}

pub struct Planning {
    project_dir: PathBuf,
    /// Next sprint, Backlog, and Done, in order.
    sections: [Vec<Story>; 3],
    open: Option<OpenStory>,
    done_expanded: bool,
    drafting: Option<DraftBox>,
    hooks: PlanningHooks,
    focus: FocusHandle,
    /// While a row is dragged: the gap it would land in.
    gap: Rc<Cell<Option<(Section, usize)>>>,
}

impl EventEmitter<()> for Planning {}

impl Focusable for Planning {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus.clone()
    }
}

impl Planning {
    pub fn new(project_dir: PathBuf, hooks: PlanningHooks, cx: &mut Context<Self>) -> Self {
        let sections = load(&project_dir);
        let this = Self {
            project_dir,
            sections,
            open: None,
            done_expanded: false,
            drafting: None,
            hooks,
            focus: cx.focus_handle(),
            gap: Rc::default(),
        };
        this.publish(cx);
        this
    }

    pub fn project_dir(&self) -> &Path {
        &self.project_dir
    }

    /// Reads the plan again from the project's data, as after a story was
    /// added where the plan isn't shown.
    pub fn reload(&mut self, cx: &mut Context<Self>) {
        let open = self.open.as_ref().map(|open| open.name.clone());
        self.sections = load(&self.project_dir);
        if open.is_some_and(|name| self.find(&name).is_none()) {
            self.open = None;
        }
        self.publish(cx);
        cx.notify();
    }

    /// The stories of `section`.
    pub fn stories(&self, section: Section) -> &[Story] {
        &self.sections[section_ix(section)]
    }

    /// Says how many stories wait in Next sprint to be sent, for the ribbon.
    pub fn publish(&self, cx: &mut App) {
        cx.set_global(SprintPending(self.unsent()));
    }

    fn unsent(&self) -> usize {
        self.sections[0].iter().filter(|story| story.task.is_none()).count()
    }

    fn find(&self, name: &str) -> Option<(Section, usize)> {
        [Section::Next, Section::Backlog, Section::Done]
            .into_iter()
            .find_map(|section| {
                self.sections[section_ix(section)]
                    .iter()
                    .position(|story| story.name == name)
                    .map(|ix| (section, ix))
            })
    }

    fn story_mut(&mut self, name: &str) -> Option<&mut Story> {
        let (section, ix) = self.find(name)?;
        self.sections[section_ix(section)].get_mut(ix)
    }

    /// Saves the order in the background.
    fn save_order(&self, cx: &mut Context<Self>) {
        let text = order_of(&self.sections);
        let dir = self.project_dir.clone();
        cx.background_spawn(async move {
            if let Err(err) = save_order_text(&dir, &text) {
                eprintln!("could not save the plan: {err:#}");
            }
        })
        .detach();
        self.publish(cx);
    }

    /// Saves the story named so in the background.
    fn save_story_named(&self, name: &str, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        let story = &self.sections[section_ix(section)][ix];
        let (file, source) = (
            story_file(&self.project_dir, &story.name),
            story.anchor.source(&story.prompt),
        );
        let dir = planning_dir(&self.project_dir);
        cx.background_spawn(async move {
            std::fs::create_dir_all(&dir).ok();
            if let Err(err) = std::fs::write(&file, source) {
                eprintln!("could not save {}: {err}", file.display());
            }
        })
        .detach();
    }

    /// Adds a story at the end of `section`, open, its title focused, in
    /// the mode last picked.
    pub fn new_story(&mut self, section: Section, window: &mut Window, cx: &mut Context<Self>) {
        self.new_story_at(section, None, window, cx);
    }

    fn new_story_at(
        &mut self,
        section: Section,
        at: Option<usize>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let section = if section == Section::Done {
            Section::Backlog
        } else {
            section
        };
        self.close_story(window, cx);
        let story = Story::new(String::new(), String::new(), last_mode(), &self.project_dir);
        let name = story.name.clone();
        let stories = &mut self.sections[section_ix(section)];
        let at = at.unwrap_or(stories.len()).min(stories.len());
        stories.insert(at, story);
        self.save_story_named(&name, cx);
        self.save_order(cx);
        self.open_story(&name, window, cx);
    }

    /// Adds a story of `mode` holding `prompt` at the end of the Backlog.
    pub fn add_story(&mut self, title: String, prompt: String, mode: SendMode, cx: &mut Context<Self>) {
        let story = Story::new(title, prompt, mode, &self.project_dir);
        let name = story.name.clone();
        self.sections[1].push(story);
        self.save_story_named(&name, cx);
        self.save_order(cx);
        cx.notify();
    }

    /// Opens the story named so beneath its row, closing any other.
    fn open_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            return;
        }
        self.close_story(window, cx);
        let Some(story) = self.story_mut(name) else {
            return;
        };
        // A draft opened is a story like any other.
        let was_draft = std::mem::take(&mut story.draft);
        let (title_text, prompt_text) = (story.title.clone(), story.prompt.clone());
        let title = cx.new(|cx| {
            InputState::new(window, cx)
                .placeholder("Story title")
                .default_value(title_text)
        });
        let prompt = cx.new(|cx| {
            EditorState::new(window, cx)
                .language(piton_syntax::LANGUAGE_NAME)
                .line_number(false)
                .folding(false)
                .soft_wrap(true)
                .scroll_beyond_last_line(Some(0))
                .cursor_surrounding_lines(Some(0))
                .placeholder("Prompt… (the title is sent where there's none)")
                .default_value(prompt_text)
        });
        let completion = cx.new(|cx| CompletionMenu::new(prompt.clone(), window, cx));
        let provider = (self.hooks.completions)(cx);
        completion.update(cx, |menu, cx| menu.set_provider(provider, cx));
        let story_name = name.to_string();
        let subscriptions = vec![
            cx.subscribe_in(&title, window, {
                let name = story_name.clone();
                move |this, input, event: &InputEvent, window, cx| match event {
                    InputEvent::Change => {
                        let value = input.read(cx).value().to_string();
                        if let Some(story) = this.story_mut(&name) {
                            story.title = value;
                        }
                        this.save_order(cx);
                        cx.notify();
                    }
                    InputEvent::PressEnter { .. } => this.title_entered(&name, window, cx),
                    _ => {}
                }
            }),
            cx.subscribe_in(&prompt, window, {
                let name = story_name.clone();
                move |this, editor, event: &InputEvent, window, cx| {
                    if matches!(event, InputEvent::Change) {
                        let value = editor.read(cx).value().to_string();
                        if let Some(story) = this.story_mut(&name) {
                            story.prompt = value;
                        }
                        this.save_story_named(&name, cx);
                        if let Some(open) = &this.open {
                            open.completion.update(cx, |menu, cx| menu.on_edit(window, cx));
                        }
                    }
                    cx.notify();
                }
            }),
        ];
        title.update(cx, |input, cx| input.focus(window, cx));
        self.open = Some(OpenStory {
            name: story_name.clone(),
            title,
            prompt,
            completion,
            fit: GrowToFit::new(PROMPT_MAX_ROWS),
            _subscriptions: subscriptions,
        });
        if was_draft {
            self.save_order(cx);
        }
        cx.notify();
    }

    /// Closes the open story; one left with neither title nor prompt is
    /// removed.
    fn close_story(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(open) = self.open.take() else {
            return;
        };
        let empty = self
            .find(&open.name)
            .map(|(section, ix)| &self.sections[section_ix(section)][ix])
            .is_some_and(|story| story.title.trim().is_empty() && story.prompt.trim().is_empty());
        if empty {
            self.delete(&open.name, cx);
        }
        self.focus.focus(window, cx);
        cx.notify();
    }

    /// Enter in an open story's title: it is kept, and another starts
    /// beneath it, so a list can be written down without the mouse.
    fn title_entered(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        if self.sections[section_ix(section)][ix].title.trim().is_empty() {
            return;
        }
        self.new_story_at(section, Some(ix + 1), window, cx);
    }

    /// Escape: closes an open completion menu, else the open story, which,
    /// left empty, goes.
    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if let Some(open) = &self.open {
            if open.completion.read(cx).is_open() {
                open.completion.update(cx, |menu, cx| menu.hide(cx));
                return;
            }
            self.close_story(window, cx);
        } else if self.drafting.as_ref().is_some_and(|draft| !draft.running) {
            self.drafting = None;
            cx.notify();
        }
    }

    /// Ctrl/Cmd+N: a story in the section of the one open, else the
    /// Backlog.
    fn new_story_here(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let section = self
            .open
            .as_ref()
            .and_then(|open| self.find(&open.name))
            .map_or(Section::Backlog, |(section, _)| section);
        self.new_story(section, window, cx);
    }

    fn delete(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        self.sections[section_ix(section)].remove(ix);
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            self.open = None;
        }
        let file = story_file(&self.project_dir, name);
        cx.background_spawn(async move {
            std::fs::remove_file(file).ok();
        })
        .detach();
        self.save_order(cx);
        cx.notify();
    }

    fn duplicate(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        let copy = self.sections[section_ix(section)][ix].duplicate();
        let copy_name = copy.name.clone();
        self.sections[section_ix(section)].insert(ix + 1, copy);
        self.save_story_named(&copy_name, cx);
        self.save_order(cx);
        cx.notify();
    }

    /// Moves the story named so to place `to` of `section`, counted as the
    /// section is before it is taken out.
    fn move_story(&mut self, name: &str, section: Section, to: usize, cx: &mut Context<Self>) {
        let Some((from_section, from)) = self.find(name) else {
            return;
        };
        let to = if from_section == section && to > from {
            to - 1
        } else {
            to
        };
        let story = self.sections[section_ix(from_section)].remove(from);
        let stories = &mut self.sections[section_ix(section)];
        stories.insert(to.min(stories.len()), story);
        self.save_order(cx);
        cx.notify();
    }

    fn move_to(&mut self, name: &str, section: Section, cx: &mut Context<Self>) {
        let end = self.sections[section_ix(section)].len();
        self.move_story(name, section, end, cx);
    }

    fn set_mode(&mut self, name: &str, mode: SendMode, cx: &mut Context<Self>) {
        if let Ok(mut last) = LAST_MODE.lock() {
            *last = Some(mode);
        }
        if let Some(story) = self.story_mut(name) {
            story.anchor.mode = Some(mode);
        }
        self.save_story_named(name, cx);
        cx.notify();
    }

    fn change(&mut self, name: &str, change: impl FnOnce(&mut HiddenAnchor), cx: &mut Context<Self>) {
        if let Some(story) = self.story_mut(name) {
            change(&mut story.anchor);
        }
        self.save_story_named(name, cx);
        cx.notify();
    }

    /// Attaches files picked to the story named so.
    fn attach(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let picked = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: true,
            prompt: Some("Attach".into()),
        });
        let (name, project_dir) = (name.to_string(), self.project_dir.clone());
        cx.spawn_in(window, async move |this, cx| {
            let Ok(Ok(Some(paths))) = picked.await else {
                return;
            };
            let saved = cx
                .background_spawn(async move {
                    let (mut images, mut files) = (Vec::new(), Vec::new());
                    for path in paths {
                        match attached_file::load(&path) {
                            Ok(attached_file::Loaded::Image(image)) => images.push(image),
                            Ok(attached_file::Loaded::File(file)) => files.push(file),
                            Err(_) => {}
                        }
                    }
                    let images = attached_image::save_all(&images, &project_dir)?;
                    let files = attached_file::save_all(&files, &project_dir)?;
                    anyhow::Ok((images, files))
                })
                .await;
            this.update(cx, |this, cx| match saved {
                Ok((images, files)) => this.change(
                    &name,
                    |anchor| {
                        anchor.attached_images.extend(images);
                        anchor.attached_files.extend(files);
                    },
                    cx,
                ),
                Err(err) => eprintln!("could not attach the files: {err:#}"),
            })
            .ok();
        })
        .detach();
    }

    /// How the story named so stands, once sent.
    fn state(&self, story: &Story, cx: &App) -> Option<StoryState> {
        let task = story.task.as_deref()?;
        Some((self.hooks.state)(task, cx).unwrap_or(StoryState::Queued))
    }

    /// Sends the stories named so, in order, as one block.
    fn send_named(&mut self, names: &[String], window: &mut Window, cx: &mut Context<Self>) {
        let mut sends = Vec::new();
        for name in names {
            let project_dir = self.project_dir.clone();
            let Some(story) = self.story_mut(name) else {
                continue;
            };
            if story.text().trim().is_empty() {
                continue;
            }
            let task = crate::prompt_title::name_for(&project_dir, &story.title);
            story.task = Some(task.clone());
            story.draft = false;
            sends.push(StorySend {
                name: task,
                title: story.title.clone(),
                text: story.text(),
                mode: story.mode(),
                attached: story.anchor.attached(),
                sliced: story.anchor.sliced,
                model: story.anchor.model.clone(),
                effort: story.anchor.effort.clone(),
            });
        }
        if sends.is_empty() {
            return;
        }
        self.save_order(cx);
        (self.hooks.send)(sends, window, cx);
        cx.notify();
    }

    /// Sends the story named so alone.
    fn send_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        self.send_named(&[name.to_string()], window, cx);
    }

    /// Sends every story of Next sprint not yet sent, in order, as one
    /// block.
    pub fn send_sprint(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let names: Vec<String> = self.sections[0]
            .iter()
            .filter(|story| story.task.is_none())
            .map(|story| story.name.clone())
            .collect();
        self.send_named(&names, window, cx);
    }

    /// Whether every story of the sprint was sent and has ended.
    fn sprint_ended(&self, cx: &App) -> bool {
        !self.sections[0].is_empty()
            && self.sections[0]
                .iter()
                .all(|story| self.state(story, cx).is_some_and(StoryState::ended))
    }

    /// Closes the sprint: the stories done go to Done; those that failed or
    /// were cancelled stay, to be sent again.
    fn close_sprint(&mut self, cx: &mut Context<Self>) {
        let stories = std::mem::take(&mut self.sections[0]);
        for mut story in stories {
            if self.state(&story, cx) == Some(StoryState::Done) {
                self.sections[2].push(story);
            } else {
                story.task = None;
                self.sections[0].push(story);
            }
        }
        self.save_order(cx);
        cx.notify();
    }

    fn open_draft_box(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.drafting.is_some() {
            return;
        }
        let input = cx.new(|cx| {
            TextareaState::new(window, cx)
                .auto_grow(2, DRAFT_MAX_ROWS)
                .placeholder("Say what you want, in a sentence or a paragraph…")
        });
        input.update(cx, |input, cx| input.focus(window, cx));
        self.drafting = Some(DraftBox {
            input,
            running: false,
            error: None,
            _run: None,
        });
        cx.notify();
    }

    /// Asks the harness to break what the box says into stories, which come
    /// back into the Backlog as drafts.
    fn draft(&mut self, cx: &mut Context<Self>) {
        let Some(drafting) = &mut self.drafting else {
            return;
        };
        let wanted = drafting.input.read(cx).value().to_string();
        if wanted.trim().is_empty() || drafting.running {
            return;
        }
        drafting.running = true;
        drafting.error = None;
        let (project_dir, ask) = (self.project_dir.clone(), self.hooks.draft);
        let run = cx.spawn(async move |this, cx| {
            let reply = cx
                .background_spawn(async move {
                    ask(&project_dir, &wanted).and_then(|reply| parse_drafts(&reply))
                })
                .await;
            this.update(cx, |this, cx| this.drafted(reply, cx)).ok();
        });
        drafting._run = Some(run);
        cx.notify();
    }

    fn drafted(&mut self, reply: Result<Vec<(String, String, SendMode)>>, cx: &mut Context<Self>) {
        match reply {
            Ok(stories) => {
                for (title, prompt, mode) in stories {
                    let mut story = Story::new(title, prompt, mode, &self.project_dir);
                    story.draft = true;
                    let name = story.name.clone();
                    self.sections[1].push(story);
                    self.save_story_named(&name, cx);
                }
                self.drafting = None;
                self.save_order(cx);
            }
            Err(err) => {
                if let Some(drafting) = &mut self.drafting {
                    drafting.running = false;
                    drafting.error = Some(format!("{err:#}"));
                }
            }
        }
        cx.notify();
    }
}

fn section_ix(section: Section) -> usize {
    match section {
        Section::Next => 0,
        Section::Backlog => 1,
        Section::Done => 2,
    }
}

/// A mode's pill: its label, small, in its colour.
fn mode_pill_label(mode: SendMode, cx: &App) -> Div {
    let color = chat_input::mode_color(mode, cx);
    div()
        .flex_none()
        .px_1p5()
        .rounded(px(4.))
        .text_xs()
        .font_medium()
        .text_color(color)
        .bg(color.opacity(0.14))
        .child(mode_label(mode))
}

/// A sent story's status, as a task's is shown: a spinner while it runs,
/// then a tick, a cross, or a dash; muted words while it waits.
fn state_mark(state: StoryState, cx: &App) -> AnyElement {
    let theme = cx.theme();
    match state {
        StoryState::Running => Spinner::new().xsmall().into_any_element(),
        StoryState::Done => Icon::new(IconName::Check)
            .xsmall()
            .text_color(crate::theme::Hue::Green.of(crate::theme::palette(cx)))
            .into_any_element(),
        StoryState::Failed => Icon::new(IconName::X)
            .xsmall()
            .text_color(crate::theme::Hue::Red.of(crate::theme::palette(cx)))
            .into_any_element(),
        StoryState::Cancelled => Icon::new(IconName::Minus)
            .xsmall()
            .text_color(theme.muted_foreground)
            .into_any_element(),
        StoryState::Queued | StoryState::Paused => div()
            .text_xs()
            .text_color(theme.muted_foreground)
            .child(state.label())
            .into_any_element(),
    }
}

impl Planning {
    fn render_section(&self, section: Section, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme();
        let muted = theme.muted_foreground;
        let stories = &self.sections[section_ix(section)];
        let count = stories.len();
        let mut heading = h_flex()
            .w_full()
            .h(px(32.))
            .gap_2()
            .items_center()
            .child(div().text_sm().font_semibold().child(section.label()))
            .child(div().text_xs().text_color(muted).child(count.to_string()))
            .child(div().flex_1());
        match section {
            Section::Next => {
                if self.sprint_ended(cx) {
                    heading = heading.child(
                        Button::new("planning-close-sprint")
                            .ghost()
                            .small()
                            .label("Close sprint")
                            .tooltip("Move the stories done to Done, leaving any that failed to send again")
                            .on_click(cx.listener(|this, _, _, cx| this.close_sprint(cx))),
                    );
                }
                let unsent = self.unsent();
                heading = heading.child(
                    Button::new("planning-send-sprint")
                        .primary()
                        .small()
                        .icon(IconName::Send)
                        .label("Send sprint")
                        .disabled(unsent == 0)
                        .tooltip(match unsent {
                            0 => "Nothing in Next sprint is waiting to be sent".to_string(),
                            1 => "Send the one story waiting, as one block".to_string(),
                            n => format!("Send the {n} stories waiting, in order, as one block"),
                        })
                        .on_click(cx.listener(|this, _, window, cx| this.send_sprint(window, cx))),
                );
            }
            Section::Backlog => {
                heading = heading.child(
                    Button::new("planning-draft-stories")
                        .ghost()
                        .small()
                        .icon(IconName::Sparkles)
                        .label("Draft stories")
                        .tooltip("Say what you want, and have the harness break it into stories")
                        .on_click(cx.listener(|this, _, window, cx| this.open_draft_box(window, cx))),
                );
            }
            Section::Done => {
                heading = gpui_kit::TestSupportExt::test_support(
                    h_flex()
                        .id("planning-done-toggle")
                        .w_full()
                        .h(px(32.))
                        .gap_2()
                        .items_center()
                        .cursor_pointer()
                        .text_color(muted)
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.done_expanded = !this.done_expanded;
                            cx.notify();
                        }))
                        .child(
                            Icon::new(if self.done_expanded {
                                IconName::ChevronDown
                            } else {
                                IconName::ChevronRight
                            })
                            .xsmall(),
                        )
                        .child(div().text_sm().font_semibold().child(section.label()))
                        .child(div().text_xs().child(count.to_string())),
                );
            }
        }
        let mut column = v_flex().w_full().gap_1().child(heading);
        if section == Section::Backlog
            && let Some(drafting) = &self.drafting
        {
            column = column.child(self.render_draft_box(drafting, cx));
        }
        if section == Section::Done && !self.done_expanded {
            return column.into_any_element();
        }
        let gap = self.gap.get();
        if stories.is_empty() {
            column = column.child(
                self.drop_zone(section, 0, div().h(ROW_HEIGHT).px_3().flex().items_center(), cx)
                    .text_sm()
                    .text_color(muted)
                    .child(section.empty()),
            );
        }
        for (ix, story) in stories.iter().enumerate() {
            let open = self.open.as_ref().filter(|open| open.name == story.name);
            column = column.child(self.render_row(section, ix, story, open.is_some(), gap, cx));
            if let Some(open) = open {
                column = column.child(self.render_open(story, open, window, cx));
            }
        }
        if section != Section::Done {
            let new_story = self
                .drop_zone(
                    section,
                    stories.len(),
                    h_flex()
                        .id(SharedString::from(format!("planning-new-story-{}", section.key())))
                        .h(px(28.))
                        .px_3()
                        .gap_2()
                        .items_center()
                        .rounded(theme.radius)
                        .cursor_pointer()
                        .text_sm()
                        .text_color(muted)
                        .hover(|row| row.bg(theme.list_hover)),
                    cx,
                )
                .on_click(cx.listener(move |this, _, window, cx| this.new_story(section, window, cx)))
                .child(Icon::new(IconName::Plus).xsmall())
                .child("New story");
            column = column.child(gpui_kit::TestSupportExt::test_support(new_story));
        }
        column.into_any_element()
    }

    /// `element` as somewhere a dragged story can be dropped, at place `at`
    /// of `section`.
    fn drop_zone(&self, section: Section, at: usize, element: impl Into<Stateful<Div>> + IntoElement + Styled + ParentElement + InteractiveElement + 'static, cx: &mut Context<Self>) -> Stateful<Div> {
        let element: Stateful<Div> = element.into();
        let gap = self.gap.clone();
        let shown = gap.get() == Some((section, at));
        element
            .relative()
            .on_drag_move(move |event: &DragMoveEvent<StoryDrag>, window, _| {
                if event.bounds.contains(&event.event.position) && gap.get() != Some((section, at)) {
                    gap.set(Some((section, at)));
                    window.refresh();
                }
            })
            .on_drop(cx.listener(move |this, drag: &StoryDrag, _, cx| {
                this.gap.set(None);
                this.move_story(&drag.name, section, at, cx);
            }))
            .when(shown, |this| {
                this.child(crate::prompt_mode::drop_indicator(false, false, cx))
            })
    }

    fn render_row(
        &self,
        section: Section,
        ix: usize,
        story: &Story,
        open: bool,
        gap: Option<(Section, usize)>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let theme = cx.theme();
        let muted = theme.muted_foreground;
        let name = story.name.clone();
        let group = SharedString::from(format!("planning-row-{}", story.name));
        let mode = story.mode();
        let state = self.state(story, cx);
        let menu_name = name.clone();
        let mode_name = name.clone();
        let this = cx.entity().downgrade();
        let mode_picker = Button::new(SharedString::from(format!("planning-mode-{}", story.name)))
            .ghost()
            .xsmall()
            .child(mode_pill_label(mode, cx))
            .tooltip("How it will be sent")
            .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, {
                let this = this.clone();
                move |mut menu, _, _| {
                    for choice in SendMode::ALL {
                        let (this, name) = (this.clone(), mode_name.clone());
                        menu = menu.item(
                            PopupMenuItem::new(mode_label(choice))
                                .checked(choice == mode)
                                .on_click(move |_, _, cx| {
                                    this.update(cx, |this, cx| this.set_mode(&name, choice, cx)).ok();
                                }),
                        );
                    }
                    menu
                }
            });
        let send_name = name.clone();
        let send = Button::new(SharedString::from(format!("planning-send-{}", story.name)))
            .ghost()
            .xsmall()
            .icon(IconName::Send)
            .label("Send")
            .tooltip("Send this story on its own")
            .on_click(cx.listener(move |this, _, window, cx| {
                cx.stop_propagation();
                this.send_story(&send_name, window, cx)
            }));
        let menu = Button::new(SharedString::from(format!("planning-menu-{}", story.name)))
            .ghost()
            .xsmall()
            .icon(IconName::Ellipsis)
            .tooltip("More")
            .dropdown_menu_with_anchor(gpui_kit::Anchor::TopRight, move |menu, _, _| {
                let item = |label: &'static str, act: fn(&mut Planning, &str, &mut Context<Planning>)| {
                    let (this, name) = (this.clone(), menu_name.clone());
                    PopupMenuItem::new(label).on_click(move |_, _, cx| {
                        this.update(cx, |this, cx| act(this, &name, cx)).ok();
                    })
                };
                let menu = match section {
                    Section::Next => menu.item(item("Move to backlog", |this, name, cx| {
                        this.move_to(name, Section::Backlog, cx)
                    })),
                    _ => menu.item(item("Move to next sprint", |this, name, cx| {
                        this.move_to(name, Section::Next, cx)
                    })),
                };
                menu.item(item("Duplicate", |this, name, cx| this.duplicate(name, cx)))
                    .separator()
                    .item(item("Delete", |this, name, cx| this.delete(name, cx)))
            });
        let dragging = cx.has_active_drag();
        let title: SharedString = if story.title.trim().is_empty() {
            "Untitled".into()
        } else {
            story.title.clone().into()
        };
        let drag = StoryDrag {
            name: name.clone(),
            title: title.clone(),
            mode,
        };
        let click_name = name.clone();
        let task = story.task.clone();
        let row = h_flex()
            .id(SharedString::from(format!("planning-story-{}", story.name)))
            .group(group.clone())
            .relative()
            .w_full()
            .h(ROW_HEIGHT)
            .flex_none()
            .px_2()
            .gap_2()
            .items_center()
            .rounded(theme.radius)
            .cursor_pointer()
            .when(open, |row| row.bg(theme.list_active))
            .when(!open, |row| row.hover(|row| row.bg(theme.list_hover)))
            .on_click(cx.listener(move |this, _, window, cx| {
                // A story sent opens its task; any other opens, or closes.
                if let Some(task) = task.as_deref().filter(|_| !open) {
                    (this.hooks.open_task)(task, window, cx);
                } else if open {
                    this.close_story(window, cx);
                } else {
                    this.open_story(&click_name, window, cx);
                }
            }))
            .on_drag(drag, |drag, _, _, cx| cx.new(|_| drag.clone()))
            .on_drag_move({
                let gap = self.gap.clone();
                move |event: &DragMoveEvent<StoryDrag>, window, _| {
                    let bounds = event.bounds;
                    if !bounds.contains(&event.event.position) {
                        return;
                    }
                    let at = ix + (event.event.position.y > bounds.center().y) as usize;
                    if gap.get() != Some((section, at)) {
                        gap.set(Some((section, at)));
                        window.refresh();
                    }
                }
            })
            .on_drop(cx.listener(move |this, drag: &StoryDrag, _, cx| {
                let at = this.gap.take().map_or(ix, |(_, at)| at);
                this.move_story(&drag.name, section, at, cx);
            }))
            .when(dragging && gap == Some((section, ix)), |row| {
                row.child(crate::prompt_mode::drop_indicator(false, false, cx))
            })
            .when(
                dragging && gap == Some((section, ix + 1)) && ix + 1 == self.sections[section_ix(section)].len(),
                |row| row.child(crate::prompt_mode::drop_indicator(false, true, cx)),
            )
            .child(
                Icon::new(IconName::GripVertical)
                    .xsmall()
                    .text_color(muted)
                    .cursor_grab(),
            )
            .child(mode_picker)
            .when(story.draft, |row| {
                row.child(div().flex_none().size(px(6.)).rounded_full().bg(theme.primary))
            })
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .truncate()
                    .text_sm()
                    .text_color(if story.title.trim().is_empty() {
                        muted
                    } else {
                        theme.foreground
                    })
                    .child(title),
            )
            .when(story.has_attachments(), |row| {
                row.child(Icon::new(IconName::Paperclip).xsmall().text_color(muted))
            })
            .children(state.map(|state| state_mark(state, cx)))
            .child(
                h_flex()
                    .flex_none()
                    .gap_0p5()
                    .invisible()
                    .group_hover(group, |this| this.visible())
                    .when(section != Section::Done, |this| this.child(send))
                    .child(menu),
            );
        gpui_kit::TestSupportExt::test_support(row).into_any_element()
    }

    fn render_open(&self, story: &Story, open: &OpenStory, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme();
        let muted = theme.muted_foreground;
        let name = story.name.clone();
        let agent = crate::agent::of_project(Some(&self.project_dir));
        let (height, _) = open.fit.heights(&open.prompt, window, cx);
        let prompt = div()
            .relative()
            .w_full()
            .child(Editor::new(&open.prompt).h(height))
            .child(GrowToFit::tracker(
                &open.prompt,
                cx.entity().downgrade(),
                |this: &mut Self| &mut this.open.as_mut().expect("a story is open").fit,
            ))
            .child(open.completion.clone());
        let attachments = {
            let mut items: Vec<(String, usize, u8)> = Vec::new();
            for (ix, text) in story.anchor.attached_text.iter().enumerate() {
                let first = text.lines().next().unwrap_or_default();
                items.push((format!("Text: {first}"), ix, 0));
            }
            for (ix, path) in story.anchor.attached_images.iter().enumerate() {
                items.push((file_name(path), ix, 1));
            }
            for (ix, path) in story.anchor.attached_files.iter().enumerate() {
                items.push((file_name(path), ix, 2));
            }
            h_flex()
                .flex_wrap()
                .gap_1()
                .children(items.into_iter().map(|(label, ix, kind)| {
                    let name = name.clone();
                    h_flex()
                        .gap_1()
                        .pl_2()
                        .rounded(px(4.))
                        .bg(theme.secondary)
                        .text_xs()
                        .child(Icon::new(IconName::Paperclip).xsmall().text_color(muted))
                        .child(div().max_w(px(220.)).truncate().child(label))
                        .child(
                            Button::new(SharedString::from(format!("planning-detach-{name}-{kind}-{ix}")))
                                .ghost()
                                .xsmall()
                                .icon(IconName::X)
                                .tooltip("Remove")
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.change(
                                        &name,
                                        |anchor| match kind {
                                            0 => {
                                                anchor.attached_text.remove(ix);
                                            }
                                            1 => {
                                                anchor.attached_images.remove(ix);
                                            }
                                            _ => {
                                                anchor.attached_files.remove(ix);
                                            }
                                        },
                                        cx,
                                    )
                                })),
                        )
                }))
                .child({
                    let name = name.clone();
                    Button::new(SharedString::from(format!("planning-attach-{name}")))
                        .ghost()
                        .xsmall()
                        .icon(IconName::Paperclip)
                        .label("Attach")
                        .tooltip("Attach files to this story")
                        .on_click(cx.listener(move |this, _, window, cx| this.attach(&name, window, cx)))
                })
        };
        // Its parameters, as the chat input shows them.
        let this = cx.entity().downgrade();
        let model = story.anchor.model.clone();
        let model_picker = {
            let (this, name) = (this.clone(), name.clone());
            Button::new(SharedString::from(format!("planning-model-{name}")))
                .ghost()
                .xsmall()
                .label(crate::models::label(agent, model.as_deref()))
                .tooltip("The model it is sent to")
                .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                    let choices = std::iter::once((None, "Default".to_string())).chain(
                        crate::models::available(agent)
                            .into_iter()
                            .map(|model| (Some(model.id), model.label)),
                    );
                    for (id, label) in choices {
                        let (this, name) = (this.clone(), name.clone());
                        let checked = id == model;
                        menu = menu.item(PopupMenuItem::new(label).checked(checked).on_click(
                            move |_, _, cx| {
                                let id = id.clone();
                                this.update(cx, |this, cx| this.change(&name, |anchor| anchor.model = id, cx))
                                    .ok();
                            },
                        ));
                    }
                    menu
                })
        };
        let efforts = crate::effort::available(agent);
        let effort = story.anchor.effort.clone();
        let effort_picker = (!efforts.is_empty()).then(|| {
            let (this, name) = (this.clone(), name.clone());
            Button::new(SharedString::from(format!("planning-effort-{name}")))
                .ghost()
                .xsmall()
                .label(crate::effort::label(agent, effort.as_deref()))
                .tooltip("The reasoning effort it is sent with")
                .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                    let choices = std::iter::once((None, "Default".to_string()))
                        .chain(efforts.iter().map(|effort| (Some(effort.id.clone()), effort.label.clone())));
                    for (id, label) in choices {
                        let (this, name) = (this.clone(), name.clone());
                        let checked = id == effort;
                        menu = menu.item(PopupMenuItem::new(label).checked(checked).on_click(
                            move |_, _, cx| {
                                let id = id.clone();
                                this.update(cx, |this, cx| this.change(&name, |anchor| anchor.effort = id, cx))
                                    .ok();
                            },
                        ));
                    }
                    menu
                })
        });
        let sliced = story.anchor.sliced;
        let slice = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-slice-{name}")))
                .ghost()
                .xsmall()
                .when(sliced, |button| button.icon(IconName::Check))
                .label("Slice")
                .tooltip("Send the slice of each spec it references, rather than links to them")
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.change(&name, |anchor| anchor.sliced = !anchor.sliced, cx)
                }))
        };
        let mode = story.mode();
        let mode_picker = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-open-mode-{name}")))
                .ghost()
                .xsmall()
                .child(mode_pill_label(mode, cx))
                .tooltip("How it will be sent")
                .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                    for choice in SendMode::ALL {
                        let (this, name) = (this.clone(), name.clone());
                        menu = menu.item(PopupMenuItem::new(mode_label(choice)).checked(choice == mode).on_click(
                            move |_, _, cx| {
                                this.update(cx, |this, cx| this.set_mode(&name, choice, cx)).ok();
                            },
                        ));
                    }
                    menu
                })
        };
        let editor = v_flex()
            .id(SharedString::from(format!("planning-open-{}", story.name)))
            .w_full()
            .gap_2()
            .p_3()
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .child(Input::new(&open.title))
            .child(prompt)
            .child(attachments)
            .child(
                h_flex()
                    .gap_1()
                    .items_center()
                    .child(mode_picker)
                    .child(model_picker)
                    .children(effort_picker)
                    .child(slice),
            );
        gpui_kit::TestSupportExt::test_support(editor).into_any_element()
    }

    fn render_draft_box(&self, drafting: &DraftBox, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme();
        let running = drafting.running;
        let draft_box = v_flex()
            .id("planning-draft-box")
            .w_full()
            .gap_2()
            .p_3()
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .child(Textarea::new(&drafting.input).disabled(running))
            .children(drafting.error.clone().map(|error| {
                div()
                    .text_xs()
                    .text_color(theme.danger)
                    .child(format!("The stories couldn't be drafted: {error}"))
            }))
            .child(
                h_flex()
                    .gap_1()
                    .justify_end()
                    .items_center()
                    .when(running, |row| {
                        row.child(Spinner::new().xsmall()).child(
                            div()
                                .text_xs()
                                .text_color(theme.muted_foreground)
                                .child("Drafting stories…"),
                        )
                    })
                    .child(
                        Button::new("planning-draft-cancel")
                            .ghost()
                            .small()
                            .label("Cancel")
                            .disabled(running)
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.drafting = None;
                                cx.notify();
                            })),
                    )
                    .child(
                        Button::new("planning-draft-run")
                            .primary()
                            .small()
                            .icon(IconName::Sparkles)
                            .label("Draft")
                            .disabled(running)
                            .on_click(cx.listener(|this, _, _, cx| this.draft(cx))),
                    ),
            );
        gpui_kit::TestSupportExt::test_support(draft_box).into_any_element()
    }
}

fn file_name(path: &str) -> String {
    Path::new(path)
        .file_name()
        .map_or_else(|| path.to_string(), |name| name.to_string_lossy().into_owned())
}

impl Render for Planning {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if !cx.has_active_drag() {
            self.gap.set(None);
        }
        if let Some(open) = &mut self.open {
            open.fit.keep_cursor_in_view(&open.prompt, window, cx);
        }
        let column = v_flex()
            .w_full()
            .max_w(COLUMN_WIDTH)
            .gap_6()
            .py_6()
            .px_4()
            .child(self.render_section(Section::Next, window, cx))
            .child(self.render_section(Section::Backlog, window, cx))
            .when(!self.sections[2].is_empty(), |column| {
                column.child(self.render_section(Section::Done, window, cx))
            });
        let planning = div()
            .id("planning")
            .key_context(CONTEXT)
            .track_focus(&self.focus)
            .size_full()
            .overflow_y_scroll()
            .bg(cx.theme().background)
            .on_action(cx.listener(|this, _: &NewStory, window, cx| this.new_story_here(window, cx)))
            .capture_action(cx.listener(|this, _: &Escape, window, cx| {
                cx.stop_propagation();
                this.escape(window, cx)
            }))
            .capture_action(cx.listener(|this, action: &Enter, window, cx| {
                // Enter accepts an open completion rather than adding a line;
                // in the draft box, Ctrl/Cmd+Enter drafts.
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                    && !action.secondary
                {
                    cx.stop_propagation();
                    open.completion
                        .update(cx, |menu, cx| menu.accept_selected(window, cx));
                } else if action.secondary && this.drafting.is_some() {
                    cx.stop_propagation();
                    this.draft(cx);
                }
            }))
            .capture_action(cx.listener(|this, _: &MoveUp, window, cx| {
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                {
                    cx.stop_propagation();
                    open.completion.update(cx, |menu, cx| menu.select_next(-1, window, cx));
                }
            }))
            .capture_action(cx.listener(|this, _: &MoveDown, window, cx| {
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                {
                    cx.stop_propagation();
                    open.completion.update(cx, |menu, cx| menu.select_next(1, window, cx));
                }
            }))
            .child(h_flex().w_full().justify_center().child(column));
        gpui_kit::TestSupportExt::test_support(planning)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn project(name: &str) -> PathBuf {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("target").join(name);
        std::fs::remove_dir_all(&dir).ok();
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    /// Stories, their order, and which section each is in come back as
    /// they were saved.
    #[test]
    fn the_plan_comes_back_as_it_was_left() {
        let dir = project("planning-save-test");
        let mut sections: [Vec<Story>; 3] = Default::default();
        let mut first = Story::new("First".into(), "Do the first thing".into(), SendMode::Code, &dir);
        first.anchor.sliced = true;
        let mut second = Story::new("Second".into(), String::new(), SendMode::Ask, &dir);
        second.draft = true;
        let mut third = Story::new("Third".into(), "Third".into(), SendMode::Spec, &dir);
        third.task = Some("ThirdTask".into());
        for story in [&first, &second, &third] {
            save_story(&dir, story).unwrap();
        }
        sections[0].push(first);
        sections[1].push(second);
        sections[2].push(third);
        save_order_text(&dir, &order_of(&sections)).unwrap();

        let loaded = load(&dir);
        let titles = loaded.each_ref().map(|stories| {
            stories.iter().map(|story| story.title.clone()).collect::<Vec<_>>()
        });
        assert_eq!(titles, [vec!["First"], vec!["Second"], vec!["Third"]]);
        assert_eq!(loaded[0][0].prompt, "Do the first thing");
        assert_eq!(loaded[0][0].mode(), SendMode::Code);
        assert!(loaded[0][0].anchor.sliced);
        assert!(loaded[1][0].draft);
        assert_eq!(loaded[1][0].mode(), SendMode::Ask);
        // A title with no prompt sends its title.
        assert_eq!(loaded[1][0].text(), "Second");
        assert_eq!(loaded[2][0].task.as_deref(), Some("ThirdTask"));
        std::fs::remove_dir_all(&dir).ok();
    }

    /// A story added where the plan isn't open goes to the end of the
    /// Backlog.
    #[test]
    fn a_story_is_added_to_the_backlog() {
        let dir = project("planning-backlog-test");
        add_to_backlog(&dir, Story::new("One".into(), "one".into(), SendMode::Code, &dir)).unwrap();
        add_to_backlog(&dir, Story::new("Two".into(), "two".into(), SendMode::Both, &dir)).unwrap();
        let loaded = load(&dir);
        assert!(loaded[0].is_empty());
        let titles: Vec<_> = loaded[1].iter().map(|story| story.title.as_str()).collect();
        assert_eq!(titles, ["One", "Two"]);
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn drafted_stories_are_read_from_the_reply() {
        let reply = r#"Here they are:
{"stories": [
  {"title": "Add sprints", "prompt": "Stories can be gathered into a sprint.", "mode": "chain"},
  {"title": "", "prompt": "Why is the queue slow?", "mode": "ask"},
  {"title": "Tidy", "prompt": "Tidy the code.", "mode": "nonsense"}
]}"#;
        let stories = parse_drafts(reply).unwrap();
        assert_eq!(
            stories,
            [
                (
                    "Add sprints".to_string(),
                    "Stories can be gathered into a sprint.".to_string(),
                    SendMode::Both
                ),
                (
                    "Why is the queue slow?".to_string(),
                    "Why is the queue slow?".to_string(),
                    SendMode::Ask
                ),
                ("Tidy".to_string(), "Tidy the code.".to_string(), SendMode::Both),
            ]
        );
        assert!(parse_drafts("no stories here").is_err());
        assert!(parse_drafts(r#"{"stories": []}"#).is_err());
    }

    #[test]
    fn the_request_holds_what_is_wanted() {
        let request = draft_request("A sprint board");
        assert!(request.ends_with("A sprint board"));
        assert!(request.contains(r#""stories""#));
    }
}

