    fn planning_tab_contents(
        &self,
        ix: usize,
        key: EntityId,
        cx: &mut Context<Self>,
    ) -> (SharedString, SharedString, AnyElement) {
        let this = cx.entity().downgrade();
        let close = close_tab_button(ix, "Close Planning", move |_, cx| {
