    pub(super) fn add_to_backlog(&mut self, text: String, mode: SendMode, cx: &mut Context<Self>) {
        let Some(planning) = self.planning(cx) else {
            return;
        };
        let title = text
            .lines()
            .map(str::trim)
            .find(|line| !line.is_empty())
            .unwrap_or_default();
